-- Provenance for bio_extended content.
-- 'template' — generated by lib/interpretations/biography.ts (formulaic)
-- 'hand'     — written by a human, never overwrite
-- 'opus'     — written by Claude Opus (high-quality, unique)
-- 'haiku'    — written by enrich-celebrities-ai.ts (Claude Haiku)
-- 'ai-other' — future-proofing for other models / providers
-- NULL       — chart_data missing or unenriched

ALTER TABLE celebrities
  ADD COLUMN IF NOT EXISTS bio_source TEXT
    CHECK (bio_source IS NULL OR bio_source IN ('template','hand','opus','haiku','ai-other'));

-- Backfill: anything currently bio_locked is hand-written. Everything else
-- with a bio_extended came from the template enricher.
UPDATE celebrities SET bio_source = 'hand'
 WHERE bio_source IS NULL AND bio_locked = true;

UPDATE celebrities SET bio_source = 'template'
 WHERE bio_source IS NULL AND bio_extended IS NOT NULL;

CREATE INDEX IF NOT EXISTS idx_celebrities_bio_source
  ON celebrities (bio_source)
  WHERE bio_source IN ('hand','opus','haiku','ai-other');
